// Delimitaciones geográficas de alta resolución basadas en la topografía real y red hídrica de la Cordillera Blanca (SRTM / IGN / OpenStreetMap)

export interface SubBasinFeature {
  id: string
  parentBasinId: string
  nombre: string
  tipo: 'quebrada' | 'hotspot_dar' | 'bofedal' | 'glaciar'
  nivelPeligro: 'Critico' | 'Alto' | 'Medio' | 'Bajo' | 'Amortiguador'
  phPromedio: number
  color: string
  descripcion: string
  coordenadas: [number, number][]
}

export interface FluvialHazardCorridor {
  id: string
  basinId: string
  nombre: string
  quebrada: string
  nivelPeligro: 'Critico' | 'Alto' | 'Medio' | 'Bajo'
  color: string
  colorFill: string
  phPromedio: number
  hierro: string
  aluminio: string
  sulfatos: string
  poblacionAfectada: string
  bofedalAmortiguador: string
  origenDrenaje: string
  descripcion: string
  thalweg: [number, number][]
}

